<script>const records=[['CapabilityDefinition','Names one HII action with owner, runtime, visibility, status, trust level, inputs, outputs, permissions, cost model, and evidence.'],['CapabilityJob','Tracks bounded work through queued, running, waiting_approval, completed, failed, or cancelled state.'],['CapabilityQuote','Captures estimated tokens, minutes, compute cost, platform fee, total, budget, currency, and quote status before execution.'],['LedgerEntry','Explains approval, reservation, compute cost, platform fee, proof, refund, quote, or top-up movement.'],['ProofArtifact','Points to reviewable evidence: log, screenshot, download, receipt, link, or JSON.']];</script><main class="-m-10 min-h-screen px-5 py-8"><div class="mx-auto max-w-5xl"><header class="border-b border-[var(--hii-electric-blue)] pb-6"><a href="/landing" class="hii-resource-link font-mono text-xs uppercase">Back to HII playbook</a><h1 class="mt-5 text-4xl font-black uppercase sm:text-6xl">HII SDK Contracts</h1></header><section class="divide-y divide-[var(--hii-electric-blue)]">{#each records as record,index}<article class="grid gap-4 py-6 md:grid-cols-[5rem_1fr]"><p class="font-mono text-4xl font-black text-[var(--hii-electric-blue)]">{String(index+1).padStart(2,'0')}</p><div><h2 class="text-2xl font-black">{record[0]}</h2><p class="mt-2 font-mono text-sm leading-7">{record[1]}</p></div></article>{/each}</section></div></main>
